<script setup lang="ts">
/**
 * Design reminder — Bright Learning Studio:
 * Use a high-contrast visual learning system: ink-blue navigation, a white
 * learning canvas, electric-blue progress, aqua evidence, coral scenarios,
 * and yellow achievements. Each lesson must instruct, vary its activity beat,
 * and show a visible learner state.
 */
import { AI_GLOSSARY, AI_MODULES, type AiModule } from '~/content/aiCourse'

type Screen = { id: string; kind: 'welcome' | 'objectives' | 'module' | 'capstone'; title: string; module?: AiModule }
type LessonPrompt = { verb: string; title: string; text: string; action: string; more: string }

const STORAGE_KEY = 'entertrainer-ai-atlas-v3'
const screens: Screen[] = [
  { id: 'welcome', kind: 'welcome', title: 'Artificial Intelligence: From Its Origins to the Frontier' },
  { id: 'objectives', kind: 'objectives', title: 'Course objectives' },
  ...AI_MODULES.map(module => ({ id: module.id, kind: 'module' as const, title: module.title, module })),
  { id: 'capstone', kind: 'capstone', title: 'Apply your learning' }
]

const termCards = [
  { term: 'Training', plain: 'The practice stage, where a system improves from examples.' },
  { term: 'Inference', plain: 'The use stage, where a trained system responds to new input.' },
  { term: 'Dataset', plain: 'A collection of examples used to train, test, or check a system.' }
]

const lessonPrompts: Record<string, LessonPrompt> = {
  bearing: { verb: 'Observe', title: 'Name the task', text: 'Choose one AI feature you used today. Identify the job it was helping you do.', action: 'Open example', more: 'See the example' },
  rules: { verb: 'Compare', title: 'Spot the difference', text: 'Decide whether a familiar task needs clear rules or useful examples.', action: 'Compare approaches', more: 'Explore the difference' },
  data: { verb: 'Connect', title: 'Think about the examples', text: 'Imagine training a photo sorter. What examples would it need?', action: 'Reveal key terms', more: 'Clarify the terms' },
  attention: { verb: 'Trace', title: 'Follow the response', text: 'Read the four stages below. Notice where your own review is required.', action: 'View the sequence', more: 'Inspect the method' },
  generation: { verb: 'Decide', title: 'Set the boundary', text: 'Choose one task where an AI draft would help, then decide what you must check.', action: 'Review the guidance', more: 'See a practical use' },
  agents: { verb: 'Map', title: 'Find the controls', text: 'Follow the path from task to human review. Each step has a purpose.', action: 'View the controls', more: 'Understand the roles' },
  embodied: { verb: 'Assess', title: 'Consider the consequence', text: 'Compare a wrong chat response with a wrong physical action.', action: 'Open the example', more: 'Consider the risk' },
  frontier: { verb: 'Verify', title: 'Check before sharing', text: 'Use the scenario to practise separating evidence from a dramatic claim.', action: 'Start scenario', more: 'Use the evidence ladder' },
  responsible: { verb: 'Apply', title: 'Run the safety check', text: 'Before using an AI tool, pause for three short questions.', action: 'Open the checklist', more: 'Review the safeguards' },
  next: { verb: 'Plan', title: 'Choose one next step', text: 'Select one low-risk task where you can test a careful AI workflow.', action: 'Open the action guide', more: 'Shape your next step' }
}

definePageMeta({ layout: false, pageTransition: { name: 'studio-fade', mode: 'out-in' } })
useHead({
  link: [
    { rel: 'preconnect', href: 'https://fonts.googleapis.com' },
    { rel: 'preconnect', href: 'https://fonts.gstatic.com', crossorigin: 'anonymous' },
    { rel: 'stylesheet', href: 'https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=DM+Serif+Display:ital@0;1&display=swap' }
  ]
})
useSeoMeta({
  title: 'Artificial Intelligence: From Its Origins to the Frontier · Entertrainer',
  description: 'A visual, beginner-friendly AI course for using today’s tools with judgement and care.',
  ogTitle: 'Artificial Intelligence: From Its Origins to the Frontier',
  ogDescription: 'A visual Entertrainer course on AI, evidence, and responsible use.'
})

const current = ref(0)
const furthest = ref(0)
const menuOpen = ref(false)
const resourcesOpen = ref(false)
const completed = ref(false)
const openExplore = ref(false)
const activeTab = ref<'rules' | 'examples'>('rules')
const revealedTerms = ref<string[]>([])
const practiceSeen = ref<string[]>([])
const diagnostic = ref('')
const learningCheck = ref('')
const scenarioChoice = ref('')
const reflection = reactive({ use: '', check: '', review: '' })

const active = computed(() => screens[current.value])
const module = computed(() => active.value.module)
const lessonPrompt = computed(() => module.value ? lessonPrompts[module.value.id] : null)
const progress = computed(() => Math.round((furthest.value / (screens.length - 1)) * 100))
const remaining = computed(() => Math.max(0, 2 - Math.round((furthest.value / (screens.length - 1)) * 2)))
const capstoneReady = computed(() => reflection.use.trim().length > 7 && reflection.check.trim().length > 7 && reflection.review.trim().length > 7)
const diagnosticFeedback = computed(() => !diagnostic.value ? '' : diagnostic.value === 'patterns' ? 'Correct. Verify what matters before you rely on the result.' : 'Try again. Confidence is not evidence.')
const learningFeedback = computed(() => !learningCheck.value ? '' : learningCheck.value === 'training' ? 'Correct. Training is the improvement stage.' : 'Try again. This describes using a trained system.')
const scenarioFeedback = computed(() => !scenarioChoice.value ? '' : scenarioChoice.value === 'check' ? 'Correct. Find official evidence or independent testing first.' : 'Pause. A post alone cannot prove a major claim.')

function persist() {
  if (!import.meta.client) return
  localStorage.setItem(STORAGE_KEY, JSON.stringify({ current: current.value, furthest: furthest.value, completed: completed.value, practiceSeen: practiceSeen.value }))
}

function go(index: number) {
  if (index < 0 || index > furthest.value + 1 || index >= screens.length) return
  current.value = index
  furthest.value = Math.max(furthest.value, index)
  openExplore.value = false
  menuOpen.value = false
  persist()
}

function next() { go(Math.min(current.value + 1, screens.length - 1)) }
function previous() { current.value = Math.max(0, current.value - 1); openExplore.value = false; persist() }
function revealTerm(term: string) { revealedTerms.value = revealedTerms.value.includes(term) ? revealedTerms.value.filter(item => item !== term) : [...revealedTerms.value, term] }
function startPrompt() {
  if (!module.value) return
  if (!practiceSeen.value.includes(module.value.id)) practiceSeen.value = [...practiceSeen.value, module.value.id]
  openExplore.value = true
  persist()
}
function finish() { if (capstoneReady.value) { completed.value = true; furthest.value = screens.length - 1; persist() } }
function restart() {
  current.value = 0; furthest.value = 0; completed.value = false; openExplore.value = false
  practiceSeen.value = []; revealedTerms.value = []; diagnostic.value = ''; learningCheck.value = ''; scenarioChoice.value = ''
  reflection.use = ''; reflection.check = ''; reflection.review = ''; persist()
}

onMounted(() => {
  const saved = localStorage.getItem(STORAGE_KEY)
  if (!saved) return
  try {
    const state = JSON.parse(saved)
    current.value = Math.min(Math.max(0, Number(state.current) || 0), screens.length - 1)
    furthest.value = Math.min(Math.max(current.value, Number(state.furthest) || 0), screens.length - 1)
    completed.value = Boolean(state.completed)
    practiceSeen.value = Array.isArray(state.practiceSeen) ? state.practiceSeen : []
  } catch { localStorage.removeItem(STORAGE_KEY) }
})
</script>

<template>
  <div class="studio-course" :class="`studio-course--${active.kind === 'module' ? module?.id : active.kind}`">
    <header class="studio-topbar">
      <NuxtLink to="/" class="studio-brand" aria-label="Return to Entertrainer home"><img :src="'https://files.manuscdn.com/user_upload_by_module/session_file/310419663032400460/uhoXkRLkUCsfcHKt.png'" alt="" /><span>Entertrainer</span></NuxtLink>
      <div class="studio-topbar__title"><span>Learning experience</span><b>AI: From Origins to the Frontier</b></div>
      <div class="studio-topbar__progress"><span>Progress</span><div><i :style="{ width: `${progress}%` }"></i></div><b>{{ progress }}%</b></div>
      <div class="studio-topbar__actions"><button type="button" @click="resourcesOpen = !resourcesOpen">Resources</button><button type="button" class="studio-menu" @click="menuOpen = !menuOpen" :aria-expanded="menuOpen"><span aria-hidden="true">☰</span> Course overview</button></div>
    </header>

    <aside class="studio-rail" aria-label="Course navigation">
      <div class="studio-rail__intro"><span>YOUR PATH</span><b>{{ progress }}% completed</b><p>{{ completed ? 'Course completed' : `${remaining || 'Less than 1'} hour remaining` }}</p></div>
      <ol class="studio-rail__list">
        <li class="studio-rail__group">Orientation</li>
        <li v-for="(screen, index) in screens.slice(0, 2)" :key="screen.id"><button type="button" :class="{ active: current === index, done: index <= furthest }" :disabled="index > furthest + 1" @click="go(index)"><i>{{ index <= furthest ? '✓' : index + 1 }}</i><span>{{ index === 0 ? 'Welcome' : 'Course objectives' }}</span></button></li>
        <li class="studio-rail__group">Explore</li>
        <li v-for="(item, index) in AI_MODULES" :key="item.id"><button type="button" :class="{ active: active.id === item.id, done: index + 2 <= furthest }" :disabled="index + 2 > furthest + 1" @click="go(index + 2)"><i>{{ index + 2 <= furthest ? '✓' : item.number }}</i><span><b>{{ item.short }}</b><small>{{ item.duration }}</small></span></button></li>
        <li class="studio-rail__group">Apply</li>
        <li><button type="button" :class="{ active: active.kind === 'capstone', done: completed }" :disabled="screens.length - 1 > furthest + 1" @click="go(screens.length - 1)"><i>{{ completed ? '✓' : '13' }}</i><span>Action plan</span></button></li>
      </ol>
      <div class="studio-rail__tip"><span>LEARNING TIP</span><p>Use the course as a guide. Pause whenever you want to test an idea in your own context.</p></div>
    </aside>

    <main class="studio-main" id="main">
      <Transition name="studio-fade" mode="out-in">
        <section :key="active.id" class="studio-screen">
          <template v-if="active.kind === 'welcome'">
            <div class="studio-hero">
              <div class="studio-hero__copy"><span class="studio-kicker">A VISUAL AI FOUNDATION · ABOUT 2 HOURS</span><h1>Navigate AI<br /><em>with judgement.</em></h1><p>Build a practical view of how AI works, where it helps, and what responsible use requires.</p><div class="studio-hero__metrics"><span><b>10</b> focused lessons</span><span><b>5</b> learner activities</span><span><b>1</b> action plan</span></div><button type="button" class="studio-primary" @click="next">Begin your learning path <span>→</span></button></div>
              <div class="studio-hero__scene"><div class="studio-hero__burst studio-hero__burst--yellow"></div><div class="studio-hero__burst studio-hero__burst--coral"></div><div class="studio-hero__ring"></div><img :src="'https://files.manuscdn.com/user_upload_by_module/session_file/310419663032400460/zByMCffPaXYvFeor.jpg'" alt="Illustrated map tracing the journey through the history of artificial intelligence." /><div class="studio-hero__badge"><span>YOUR DESTINATION</span><b>Use AI with clarity, evidence, and care.</b></div></div>
            </div>
            <section class="studio-route"><div><i>01</i><span><b>Orient</b> Build a simple mental model.</span></div><div><i>02</i><span><b>Examine</b> Compare tools and evidence.</span></div><div><i>03</i><span><b>Apply</b> Make one responsible choice.</span></div></section>
          </template>

          <template v-else-if="active.kind === 'objectives'">
            <article class="studio-objectives"><div class="studio-objectives__head"><span class="studio-kicker">START WITH PURPOSE</span><h2>By the End of this module, you will be able to:</h2><p>Use these three outcomes to guide your attention through the course.</p></div><div class="studio-objectives__cards"><div><i>01</i><b>Explain</b><span>the major stages in AI development.</span></div><div><i>02</i><b>Distinguish</b><span>common AI approaches and capabilities.</span></div><div><i>03</i><b>Evaluate</b><span>claims using evidence and limitations.</span></div></div><div class="studio-objectives__note"><span>WORKING PRINCIPLE</span><b>Separate facts, reported claims, rumours, and future possibilities.</b></div><button type="button" class="studio-primary" @click="next">Enter Lesson 1 <span>→</span></button></article>
          </template>

          <template v-else-if="active.kind === 'module' && module">
            <article class="studio-lesson">
              <header class="studio-lesson__header"><div class="studio-lesson__number"><span>LESSON</span><b>{{ module.number }}</b></div><div><p class="studio-kicker">{{ module.duration }} · {{ lessonPrompt?.verb }} THE CONCEPT</p><h2>{{ module.title }}</h2><p>{{ module.blurb }}</p></div><div class="studio-lesson__orbit"><span>{{ module.number }}</span></div></header>

              <section v-if="lessonPrompt" class="studio-instruction"><div class="studio-instruction__verb">{{ lessonPrompt.verb }}</div><div><span class="studio-label">YOUR FIRST MOVE</span><h3>{{ lessonPrompt.title }}</h3><p>{{ lessonPrompt.text }}</p><div class="studio-instruction__actions"><button type="button" @click="startPrompt">{{ lessonPrompt.action }} <span>→</span></button><small v-if="practiceSeen.includes(module.id)">✓ Exploration opened</small></div></div></section>

              <section v-if="module.visual === 'history'" class="studio-media studio-media--history"><img :src="'https://files.manuscdn.com/user_upload_by_module/session_file/310419663032400460/lMkColbiQZRDDmAi.jpg'" alt="Visual timeline from early mechanical calculation to modern AI models." /><div><span>VISUAL CUE</span><b>Notice the shift: written rules → learned patterns.</b></div></section>
              <section v-if="module.visual === 'agents'" class="studio-media studio-media--agents"><img :src="'https://files.manuscdn.com/user_upload_by_module/session_file/310419663032400460/MivTADgxAPaQaRCw.jpg'" alt="Visual map of AI tools, planning, and human review." /><div><span>VISUAL CUE</span><b>Find the human review point in the workflow.</b></div></section>

              <section class="studio-concept"><div class="studio-concept__mark">✦</div><div><span class="studio-label">CORE CONCEPT</span><template v-if="module.id === 'bearing'"><h3>AI supports a specific task.</h3><p>Judge the tool by the job it helps to complete.</p></template><template v-else-if="module.id === 'rules'"><h3>AI may use rules or examples.</h3><p>Select the method that fits the task.</p></template><template v-else-if="module.id === 'data'"><h3>AI learns from examples.</h3><p>It uses that learning on new input.</p></template><template v-else-if="module.id === 'attention'"><h3>Modern AI weighs relevant context.</h3><p>This helps it respond across many topics.</p></template><template v-else-if="module.id === 'generation'"><h3>Generative AI creates a first draft.</h3><p>Review it before you rely on it.</p></template><template v-else-if="module.id === 'agents'"><h3>Agents can take approved steps.</h3><p>Limits and review keep the work safe.</p></template><template v-else-if="module.id === 'embodied'"><h3>Real-world AI needs stronger safeguards.</h3><p>Physical mistakes can have serious consequences.</p></template><template v-else-if="module.id === 'frontier'"><h3>Strong claims need strong evidence.</h3><p>Check the source before you share.</p></template><template v-else-if="module.id === 'responsible'"><h3>Responsible use starts before the prompt.</h3><p>Protect data and consider who may be affected.</p></template><template v-else><h3>Start small and check the result.</h3><p>Use AI where the risk is low and review is easy.</p></template></div></section>

              <section class="studio-expand"><button type="button" :aria-expanded="openExplore" @click="openExplore = !openExplore"><span><b>{{ lessonPrompt?.more || 'Explore the detail' }}</b><small>Open a short explanation</small></span><i>{{ openExplore ? '−' : '+' }}</i></button><div v-if="openExplore"><span class="studio-label">EXPLANATION</span><h3>{{ module.exploreTitle }}</h3><p>{{ module.exploreText }}</p></div></section>

              <section v-if="module.id === 'rules'" class="studio-compare"><div><span class="studio-label">COMPARE</span><h3>Choose a method.</h3></div><div class="studio-tabs" role="tablist"><button type="button" :class="{ active: activeTab === 'rules' }" :aria-selected="activeTab === 'rules'" @click="activeTab = 'rules'"><i>01</i> Written rules</button><button type="button" :class="{ active: activeTab === 'examples' }" :aria-selected="activeTab === 'examples'" @click="activeTab = 'examples'"><i>02</i> Past examples</button></div><div class="studio-compare__panel"><template v-if="activeTab === 'rules'"><b>Written rules</b><p>People define the instructions.</p><small>Use when the rule is clear.</small></template><template v-else><b>Past examples</b><p>The system learns a pattern.</p><small>Use when results can be checked.</small></template></div></section>

              <section v-if="module.id === 'data'" class="studio-flashcards"><div><span class="studio-label">REVEAL</span><h3>Tap each term.</h3></div><div class="studio-flashcards__grid"><button v-for="card in termCards" :key="card.term" type="button" :class="{ revealed: revealedTerms.includes(card.term) }" @click="revealTerm(card.term)"><span v-if="!revealedTerms.includes(card.term)"><b>{{ card.term }}</b><small>Tap to reveal</small></span><span v-else><b>{{ card.term }}</b><small>{{ card.plain }}</small></span></button></div></section>

              <section v-if="module.id === 'attention'" class="studio-process"><span class="studio-label">TRACE THE PROCESS</span><h3>From prompt to response</h3><ol><li><b>01</b><span>You give a prompt.</span></li><li><b>02</b><span>The model weighs context.</span></li><li><b>03</b><span>It creates a likely response.</span></li><li><b>04</b><span>You review the output.</span></li></ol></section>

              <section v-if="module.id === 'agents'" class="studio-flow"><div><span class="studio-label">MAP THE CONTROL POINTS</span><h3>A safe agent needs a clear path.</h3></div><div class="studio-flow__steps"><span>Task</span><i>→</i><span>Tools</span><i>→</i><span>Limits</span><i>→</i><span>Review</span></div></section>

              <section v-if="module.video" class="studio-video"><div class="studio-video__icon">▶</div><div><span class="studio-label">OPTIONAL EXTENSION</span><h3>{{ module.video.title }}</h3><p>Watch to reinforce the concept in a different format.</p><a :href="module.video.url" target="_blank" rel="noreferrer">Watch the video <span>↗</span></a></div></section>

              <section v-if="module.id === 'bearing'" class="studio-check studio-check--blue"><div><span class="studio-label">CHECK YOUR JUDGEMENT</span><h3>What should you do with an important AI answer?</h3></div><div class="studio-options"><button type="button" :class="{ selected: diagnostic === 'patterns' }" @click="diagnostic = 'patterns'"><i>A</i><span>Check it with a reliable source.</span></button><button type="button" :class="{ selected: diagnostic === 'trust' }" @click="diagnostic = 'trust'"><i>B</i><span>Trust it because it sounds confident.</span></button></div><p v-if="diagnosticFeedback" :class="{ correct: diagnostic === 'patterns' }">{{ diagnosticFeedback }}</p></section>

              <section v-if="module.id === 'data'" class="studio-check studio-check--purple"><div><span class="studio-label">CHECK YOUR UNDERSTANDING</span><h3>Which describes training?</h3></div><div class="studio-options studio-options--stack"><button type="button" :class="{ selected: learningCheck === 'inference' }" @click="learningCheck = 'inference'"><i>A</i><span>Using a trained tool on a new prompt.</span></button><button type="button" :class="{ selected: learningCheck === 'training' }" @click="learningCheck = 'training'"><i>B</i><span>Improving a system with examples and feedback.</span></button></div><p v-if="learningFeedback" :class="{ correct: learningCheck === 'training' }">{{ learningFeedback }}</p></section>

              <section v-if="module.id === 'frontier'" class="studio-scenario"><div class="studio-scenario__side"><span>SCENARIO</span><b>08</b></div><div class="studio-scenario__body"><span class="studio-label">VERIFY BEFORE YOU SHARE</span><h3>A post makes a dramatic AI claim.</h3><p>Choose your first response.</p><div class="studio-options studio-options--stack"><button type="button" :class="{ selected: scenarioChoice === 'check' }" @click="scenarioChoice = 'check'"><i>A</i><span>Look for official evidence or independent testing.</span></button><button type="button" :class="{ selected: scenarioChoice === 'share' }" @click="scenarioChoice = 'share'"><i>B</i><span>Share it immediately.</span></button></div><p v-if="scenarioFeedback" :class="{ correct: scenarioChoice === 'check' }">{{ scenarioFeedback }}</p></div></section>

              <section v-if="module.id === 'responsible'" class="studio-checklist"><div><span class="studio-label">APPLY THE SAFETY CHECK</span><h3>Pause for three questions.</h3></div><ul><li><i>01</i><span>Is private information protected?</span></li><li><i>02</i><span>Will I check important outputs?</span></li><li><i>03</i><span>Is a person accountable?</span></li></ul></section>

              <section class="studio-evidence"><div><span>Evidence note</span><b>{{ module.confidence }}</b><p>{{ module.sourceLabel }}</p></div><a :href="module.sourceUrl" target="_blank" rel="noreferrer">Open evidence <span>↗</span></a></section>
              <section class="studio-takeaway"><span>REMEMBER</span><p>{{ module.takeaway }}</p><i>✦</i></section>
              <div class="studio-continue"><div><span>LESSON {{ module.number }}</span><b>Ready for the next idea?</b></div><button type="button" class="studio-primary" @click="next">{{ current < screens.length - 2 ? 'Continue to next lesson' : 'Create your action plan' }} <span>→</span></button></div>
            </article>
          </template>

          <template v-else>
            <article class="studio-capstone"><header><span class="studio-kicker">FINAL APPLICATION</span><h2>Turn one idea<br />into <em>practice.</em></h2><p>Create a short plan for using AI responsibly in your own work or learning.</p></header><form @submit.prevent="finish"><div class="studio-capstone__step"><i>01</i><label><b>Choose a low-risk task.</b><span>Start with something you can review easily.</span><textarea v-model="reflection.use" rows="2" placeholder="For example: Draft a training outline."></textarea></label></div><div class="studio-capstone__step"><i>02</i><label><b>State what you will check.</b><span>Think about facts, policies, or sources.</span><textarea v-model="reflection.check" rows="2" placeholder="For example: Check every source."></textarea></label></div><div class="studio-capstone__step"><i>03</i><label><b>Name the review step.</b><span>Who confirms the final result?</span><textarea v-model="reflection.review" rows="2" placeholder="For example: A subject expert reviews it."></textarea></label></div><div class="studio-capstone__submit"><p>Complete the three steps to record your learning.</p><button type="submit" class="studio-primary" :disabled="!capstoneReady">{{ completed ? 'Course completed' : 'Complete course' }} <span>→</span></button></div></form><div v-if="completed" class="studio-complete"><i>✓</i><div><span>COMPLETION RECORDED</span><h3>You have completed the course.</h3><p>Carry the habit forward: start small, check important work, and remain accountable.</p></div><button type="button" @click="restart">Restart</button></div></article>
          </template>
        </section>
      </Transition>
    </main>

    <footer class="studio-footer"><button type="button" :disabled="current === 0" @click="previous">← Previous</button><div><i :style="{ width: `${progress}%` }"></i></div><span>{{ current + 1 }} / {{ screens.length }}</span><button type="button" :disabled="current === screens.length - 1" @click="next">Next →</button></footer>

    <aside v-if="menuOpen" class="studio-drawer" aria-label="Course overview" role="dialog" aria-modal="true"><header><div><span>LEARNING PATH</span><h2>Course overview</h2></div><button type="button" @click="menuOpen = false" aria-label="Close course overview">×</button></header><ol><li v-for="(screen, index) in screens" :key="screen.id"><button type="button" :class="{ active: index === current, done: index <= furthest }" :disabled="index > furthest + 1" @click="go(index)"><i>{{ index <= furthest ? '✓' : String(index + 1).padStart(2, '0') }}</i><span>{{ screen.kind === 'module' ? screen.module?.short : screen.title }}</span><small v-if="screen.kind === 'module'">{{ screen.module?.duration }}</small></button></li></ol></aside>
    <aside v-if="resourcesOpen" class="studio-drawer studio-drawer--resources" aria-label="Course resources" role="dialog" aria-modal="true"><header><div><span>REFERENCE LIBRARY</span><h2>Resources</h2></div><button type="button" @click="resourcesOpen = false" aria-label="Close resources">×</button></header><p>Use these plain-language definitions to support your learning.</p><dl><div v-for="item in AI_GLOSSARY" :key="item[0]"><dt>{{ item[0] }}</dt><dd>{{ item[1] }}</dd></div></dl><a href="/docs/ai-course-research.md">Open source register <span>↗</span></a></aside>
  </div>
</template>

<style>
/* Bright Learning Studio — visual, instructional, varied, and high contrast. */
